INSERT INTO public.client_master_options (category, label, value)
SELECT 'country', V. Label, V. Label
FROM (
  VALUES
    ('India')
) AS v(label)
WHERE NOT EXISTS (
  SELECT 1 FROM public.client_master_options o
  WHERE O. Category = 'country' AND O. Label = V. Label
);

INSERT INTO public.client_master_options (category, label, value)
SELECT 'country_code', V. Label, V. Label
FROM (
  VALUES
    ('+91')
) AS v(label)
WHERE NOT EXISTS (
  SELECT 1 FROM public.client_master_options o
  WHERE O. Category = 'country_code' AND O. Label = V. Label
);

